<script setup lang="ts">
import { FLOAT_TOL, GRAPH_FONT_SIZE, GRAPH_HEIGHT } from "@/Utils/Constants";
import { cssVar } from "@/Utils/Helpers";
import { computed, onBeforeUnmount, onMounted, ref } from "vue";
import HoverTip from "@/Components/Common/HoverTip.vue";

type DataPoint = [number, number];

type Point = {
  x: number;
  y: number;
  cumulativeY: number; // Always stores the raw cumulative Y regardless of slope calculation
};

const props = withDefaults(
  defineProps<{
    data: DataPoint[] | null | undefined;
    graphColor?: string;
    cumulative: boolean;
    height?: number;
    materialLabel: string;
    // Generalized Annotations
    annotations?: (number | null)[];
    annotationColors?: string[];
    annotationPositions?: ("top" | "middle" | "bottom" | "graph")[];
    annotationLabels?: string[];
    maxYoverride?: number;
    // Tooltip Function
    tooltipTextFn?: (
      x: number,
      y: number,
      cumulativeY: number,
      material: string,
      color: string,
      is_last: boolean,
    ) => string;
    empty_message?: string;
    upside_down?: boolean;
    histogram?: boolean;
  }>(),
  {
    graphColor: "--text-main",
    height: 40,
    annotations: () => [],
    annotationColors: () => [],
    annotationPositions: () => [],
    annotationLabels: () => [],
    // Default tooltip just displays values
    tooltipTextFn: (x, y, cy, _material, _color, _is_last) =>
      `<b>X:</b> ${x} <br/> <b>Y:</b> ${cy}`,
    empty_message: "This material is never used",
    upside_down: false,
    histogram: false,
  },
);

const rootRef = ref<HTMLElement | null>(null);
const svgRef = ref<SVGSVGElement | null>(null);
const width = ref(0);
const mouseX = ref<number | null>(null);
let observer: ResizeObserver | null = null;
const MIN_GRAPH_WIDTH = 180;

const plotWidth = computed(() => Math.max(MIN_GRAPH_WIDTH, width.value));

const points = computed<Point[]>(() => {
  if (!Array.isArray(props.data) || props.data.length === 0) {
    return [];
  }

  let normalized = props.data
    .map(
      (pair) => [Number(pair?.[0] ?? 0), Number(pair?.[1] ?? 0)] as DataPoint,
    )
    .filter((pair) => Number.isFinite(pair[0]) && Number.isFinite(pair[1]));

  // console.log(normalized);
  if (normalized.length < 2) {
    return normalized.map(([x, y]) => ({ x, y, cumulativeY: y }));
  }

  if (props.cumulative) {
    return normalized.map(([x, y]) => ({ x, y, cumulativeY: y }));
  }

  let prevSlope = 0;

  return normalized.map(([x, y], index) => {
    if (index === 0) {
      const nextX = normalized[1][0];
      const dx = nextX - x;
      const slope = dx === 0 ? 0 : props.upside_down ? (1 - y) / dx : y / dx;
      prevSlope = slope;

      return { x, y: slope, cumulativeY: y };
      // no upside down multiplier cos its always positive
    }

    const [prevX, prevY] = normalized[index - 1];
    // let this_gap = x - prevX
    // if (Math.abs(this_gap - gap_size) > FLOAT_TOL) {
    //     return { x, y: prevSlope, cumulativeY: y }
    // }
    // we will just assume gap is constant, (non-cumulative graph looks weird otherwise), which is the current behaviour of histogram
    const dx = x - prevX;
    const slope =
      dx === 0 ? 0 : ((y - prevY) * (props.upside_down ? -1 : 1)) / dx;

    if (!props.histogram && Math.abs(slope) < FLOAT_TOL) {
      const out = { x, y: prevSlope, cumulativeY: y };
      prevSlope = 0;
      return out;
    }
    prevSlope = slope;

    return { x, y: slope, cumulativeY: y };
  });
});

const maxX = computed(() => {
  if (!points.value.length) return 0;
  return Math.max(0, ...points.value.map((point) => point.x));
});

const maxY = computed(() => {
  if (!points.value.length) return 1;
  if (props.maxYoverride && props.cumulative) {
    return props.maxYoverride;
  }
  return Math.max(1e-9, ...points.value.map((point) => point.y));
});

const isEmpty = computed(() => points.value.length === 0);

function scaleX(x: number) {
  if (maxX.value <= 0) return 0;
  return (x / maxX.value) * plotWidth.value;
}

function scaleY(y: number) {
  if (maxY.value <= 0) return GRAPH_HEIGHT;
  const normalized = y / (maxY.value * 1.1);
  return Math.max(
    0,
    Math.min(GRAPH_HEIGHT, GRAPH_HEIGHT - normalized * GRAPH_HEIGHT),
  );
}

function interpolateY(targetX: number) {
  const list = points.value;
  if (!list.length) return GRAPH_HEIGHT;
  // console.log(targetX);
  if (targetX < list[0].x)
    return props.histogram && targetX >= firstBarX.value
      ? scaleY(list[0].y)
      : GRAPH_HEIGHT;

  for (let index = 1; index < list.length; index++) {
    const prev = list[index - 1];
    const cur = list[index];
    if (targetX <= cur.x) {
      if (centered.value)
        return scaleY(targetX < (prev.x + cur.x) / 2 ? prev.y : cur.y);
      const dx = cur.x - prev.x;
      const t = stepped.value ? 1 : dx === 0 ? 0 : (targetX - prev.x) / dx;
      const y = prev.y + (cur.y - prev.y) * t;
      return scaleY(y);
    }
  }

  return scaleY(list[list.length - 1].y);
}
// step drawing when forced or when cumulative Y repeats
const stepped = computed(() => {
  if (props.histogram) return true;
  return (
    !props.upside_down &&
    points.value.filter(
      (p) =>
        p.cumulativeY !== points.value[0].cumulativeY && p.cumulativeY !== 1.0,
    ).length !==
      new Set(
        points.value
          .filter(
            (p) =>
              p.cumulativeY !== points.value[0].cumulativeY &&
              p.cumulativeY !== 1.0,
          )
          .map((x) => x.cumulativeY),
      ).size
  );
});

// a stepped non-histogram centres each bar on its point, so the ends are half bars
const centered = computed(() => stepped.value && !props.histogram);

// a histogram's first point gets a bar one gap wide to its left
const firstBarX = computed(() => {
  const pts = points.value;
  if (pts.length < 2) return pts[0]?.x ?? 0;
  return Math.max(0, pts[0].x - (pts[1].x - pts[0].x));
});

const linePath = computed(() => {
  if (!points.value.length) return "";
  const pts = points.value;
  if (centered.value) {
    const parts = [
      `M 0 ${GRAPH_HEIGHT}`,
      `L ${scaleX(pts[0].x)} ${GRAPH_HEIGHT}`,
      `L ${scaleX(pts[0].x)} ${scaleY(pts[0].y)}`,
    ];
    for (let i = 1; i < pts.length; i++) {
      const mid = scaleX((pts[i - 1].x + pts[i].x) / 2);
      parts.push(`L ${mid} ${scaleY(pts[i - 1].y)}`);
      parts.push(`L ${mid} ${scaleY(pts[i].y)}`);
    }
    parts.push(
      `L ${scaleX(pts[pts.length - 1].x)} ${scaleY(pts[pts.length - 1].y)}`,
    );
    return parts.join(" ");
  }
  if (stepped.value) {
    const parts = [
      `M ${scaleX(firstBarX.value)} ${GRAPH_HEIGHT}`,
      `L ${scaleX(firstBarX.value)} ${scaleY(pts[0].y)}`,
      `L ${scaleX(pts[0].x)} ${scaleY(pts[0].y)}`,
    ];
    for (let i = 1; i < pts.length; i++) {
      parts.push(`L ${scaleX(pts[i - 1].x)} ${scaleY(pts[i].y)}`);
      parts.push(`L ${scaleX(pts[i].x)} ${scaleY(pts[i].y)}`);
    }
    return parts.join(" ");
  }
  return [`M ${scaleX(pts[0].x)} ${GRAPH_HEIGHT}`]
    .concat(pts.map((point) => `L ${scaleX(point.x)} ${scaleY(point.y)}`))
    .join(" ");
});

const areaPath = computed(() => {
  if (!points.value.length) return "";
  const firstX = scaleX(props.histogram ? firstBarX.value : points.value[0].x);
  const lastX = scaleX(points.value[points.value.length - 1].x);
  if (stepped.value) {
    return `${linePath.value} L ${lastX} ${GRAPH_HEIGHT} L ${firstX} ${GRAPH_HEIGHT} Z`;
  } else {
    return `${linePath.value} L ${lastX} ${GRAPH_HEIGHT} Z`;
  }
});

// Mouse and Hover Logic
function onMouseMove(event: MouseEvent) {
  if (!rootRef.value) return;
  const rect = rootRef.value.getBoundingClientRect();
  mouseX.value = event.clientX - rect.left;
}

function onMouseLeave() {
  mouseX.value = null;
}

// a histogram's point is hovered at the centre of its bar
function hoverX(point: Point) {
  if (!props.histogram) return point.x;
  const index = points.value.indexOf(point);
  const left = index === 0 ? firstBarX.value : points.value[index - 1].x;
  return (left + point.x) / 2;
}

// the hovered dot in viewport coordinates, where the tooltip is pinned
function dotPosition(point: Point) {
  const rect = svgRef.value!.getBoundingClientRect();
  return {
    x: rect.left + scaleX(hoverX(point)),
    y: rect.top + scaleY(point.y),
  };
}

const hoveredPoint = computed(() => {
  if (mouseX.value === null || !points.value.length) return null;

  // Snap to the closest point along the X axis
  let closest = points.value[0];
  let minDistance = Math.abs(scaleX(hoverX(closest)) - mouseX.value);
  // console.log("before", closest);
  for (const point of points.value) {
    const dist = Math.abs(scaleX(hoverX(point)) - mouseX.value);
    if (dist < minDistance) {
      minDistance = dist;
      closest = point;
    }
  }
  // console.log("aft", closest);
  return closest;
});

// Generalize Annotations Output
function clamp(value: number, min: number, max: number) {
  return Math.max(min, Math.min(max, value));
}

function badgeWidth(text: string) {
  return Math.min(220, (text.length * GRAPH_FONT_SIZE) / 2); // why / 2 ? idk
}

const processedAnnotations = computed(() => {
  if (isEmpty.value) return [];

  // a null annotation is not drawn; the others keep their colour and label
  return props.annotations
    .map((xVal, i) => {
      if (xVal === null) return null;
      const color = cssVar(props.annotationColors[i] || "white", "white");
      const positionStr = props.annotationPositions[i] || "top";
      const label = props.annotationLabels[i] || "";

      const svgX = scaleX(xVal);
      const svgY = interpolateY(xVal);
      const textW = badgeWidth(label);

      // Clamp text X so it never falls off the chart left/right
      // console.log(label, xVal, svgX, textW, textW / 2)
      const clampedX = clamp(svgX, textW / 2, plotWidth.value - textW / 2);

      let textY = GRAPH_FONT_SIZE + 4;
      if (positionStr === "bottom") textY = GRAPH_HEIGHT;
      if (positionStr === "middle")
        textY = (GRAPH_HEIGHT + GRAPH_FONT_SIZE + 4) / 2;
      if (positionStr === "graph")
        textY = clamp(
          svgY - GRAPH_FONT_SIZE,
          GRAPH_FONT_SIZE + 4,
          GRAPH_HEIGHT - GRAPH_FONT_SIZE,
        );
      return {
        xVal,
        svgX,
        svgY,
        color,
        label,
        textY,
        clampedX,
      };
    })
    .filter((annotation) => annotation !== null);
});

const resolvedColor = computed(() =>
  cssVar(props.graphColor, props.graphColor),
);
const axisColor = computed(() => cssVar("--text-very-muted", "#9aa3b2"));
const surfaceTextColor = computed(() => cssVar("--text-main", "#c9d0da"));

onMounted(() => {
  const updateWidth = () => {
    if (!rootRef.value) return;
    width.value = Math.max(
      MIN_GRAPH_WIDTH,
      Math.floor(rootRef.value.getBoundingClientRect().width),
    );
  };

  updateWidth();
  observer = new ResizeObserver(updateWidth);
  if (rootRef.value) {
    observer.observe(rootRef.value);
  }
});

onBeforeUnmount(() => {
  observer?.disconnect();
  observer = null;
});
</script>

<template>
  <div
    ref="rootRef"
    class="material-graph"
    @mousemove="onMouseMove"
    @mouseleave="onMouseLeave"
  >
    <HoverTip
      class="block"
      placement="left"
      :sticky="false"
      :anchor="hoveredPoint && (() => dotPosition(hoveredPoint!))"
    >
      <svg
        ref="svgRef"
        :width="Math.max(width, MIN_GRAPH_WIDTH)"
        :height="height"
        role="img"
        aria-label="Material graph"
      >
        <defs>
          <linearGradient
            :id="`graph-fill-${graphColor.replace(/[^a-z0-9]/gi, '')}`"
            x1="0"
            y1="0"
            x2="0"
            y2="1"
          >
            <stop offset="0%" :stop-color="resolvedColor" stop-opacity="0.38" />
            <stop
              offset="100%"
              :stop-color="resolvedColor"
              stop-opacity="0.08"
            />
          </linearGradient>
        </defs>

        <g>
          <line
            x1="0"
            :x2="plotWidth"
            :y1="GRAPH_HEIGHT"
            :y2="GRAPH_HEIGHT"
            :stroke="axisColor"
            stroke-width="1"
          />

          <path
            v-if="!isEmpty"
            :d="areaPath"
            :fill="`url(#graph-fill-${graphColor.replace(/[^a-z0-9]/gi, '')})`"
            stroke="none"
          />
          <path
            v-if="!isEmpty"
            :d="linePath"
            fill="none"
            :stroke="resolvedColor"
            stroke-width="2.1"
          />

          <g v-for="(annotation, index) in processedAnnotations" :key="index">
            <line
              :x1="annotation.svgX"
              :x2="annotation.svgX"
              :y1="GRAPH_HEIGHT"
              :y2="annotation.svgY"
              :stroke="annotation.color"
              stroke-width="1"
              stroke-dasharray="4 4"
            />
            <circle
              :cx="annotation.svgX"
              :cy="annotation.svgY"
              r="3.5"
              :fill="annotation.color"
            />

            <text
              :x="annotation.clampedX"
              :y="annotation.textY"
              text-anchor="middle"
              :font-size="GRAPH_FONT_SIZE"
              :fill="annotation.color"
            >
              {{ annotation.label }}
            </text>
          </g>

          <g v-if="hoveredPoint">
            <line
              :x1="scaleX(hoverX(hoveredPoint))"
              :x2="scaleX(hoverX(hoveredPoint))"
              :y1="GRAPH_HEIGHT"
              :y2="scaleY(hoveredPoint.y)"
              stroke="var(--graph-hover-color, #ffffff)"
              stroke-width="1"
            />
            <circle
              :cx="scaleX(hoverX(hoveredPoint))"
              :cy="scaleY(hoveredPoint.y)"
              r="4"
              fill="var(--graph-hover-color, #ffffff)"
            />
          </g>

          <text
            v-if="isEmpty"
            x="4"
            :y="Math.max(16, GRAPH_HEIGHT * 0.55)"
            font-size="12"
            :fill="surfaceTextColor"
            opacity="0.85"
          >
            {{ empty_message }}
          </text>
        </g>
      </svg>
      <template #tip>
        <span
          v-if="hoveredPoint"
          v-html="
            props.tooltipTextFn!(
              hoveredPoint.x,
              hoveredPoint.y,
              hoveredPoint.cumulativeY,
              materialLabel,
              resolvedColor,
              hoveredPoint == points[points.length - 1],
            )
          "
        />
      </template>
    </HoverTip>
  </div>
</template>

<style scoped>
.material-graph {
  width: 100%;
  cursor: crosshair; /* Helps signal it's interactive */
  height: 41px;
  padding-left: 0.5rem;
}
</style>
