const romanNumeralReplacements = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII', 'L', 'C', 'D', 'M'].flatMap((value, index) => [
	[String.fromCodePoint(0x21_60 + index), value],
	[String.fromCodePoint(0x21_70 + index), value.toLowerCase()],
]);

